import { createHash } from 'node:crypto';
import { execFile } from 'node:child_process';
import { lstatSync, mkdirSync, readFileSync, renameSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { promisify } from 'node:util';

export const files = ['journal.py', 'planner.py', 'policy.py', 'release.py'];
export const digest = value => createHash('sha256').update(value).digest('hex');
const exec = promisify(execFile);

export function snapshot(root) {
  const result = {};
  for (const path of files) {
    const target = join(root, path);
    try {
      const stat = lstatSync(target);
      if (!stat.isFile() || stat.isSymbolicLink() || stat.size > 128 * 1024) throw Error('Unsafe source: ' + path);
      result[path] = readFileSync(target);
    } catch (error) { if (error.code !== 'ENOENT') throw error; }
  }
  return result;
}

export function rows(bytes) {
  return files.map(path => ({ path, sha256: bytes[path] ? digest(bytes[path]) : null }));
}

export function fingerprint(bytes) {
  return digest(JSON.stringify(rows(bytes)));
}

export function save(root, name, value) {
  const target = join(root, name);
  mkdirSync(dirname(target), { recursive: true });
  const next = target + '.next';
  writeFileSync(next, typeof value === 'string' ? value : JSON.stringify(value, null, 2) + '\n');
  renameSync(next, target);
}

export function materialize(root, bytes) {
  mkdirSync(root, { recursive: true });
  for (const path of files) if (bytes[path]) writeFileSync(join(root, path), bytes[path]);
}

export function linux(path) {
  const text = resolve(path).replaceAll('\\', '/');
  if (!/^G:\/CodexProjects\/DSH\/outputs\//iu.test(text)) throw Error('Native WSL test path must stay on the G QA drive: ' + text);
  return '/mnt/g' + text.slice(2);
}

export async function evaluate({ fixture, temp, source, stage }) {
  mkdirSync(temp, { recursive: true });
  const command = ['-d', 'Ubuntu', '--exec', '/usr/bin/env', 'TMPDIR=' + linux(temp), 'PYTHONDONTWRITEBYTECODE=1',
    '/usr/bin/python3', linux(fixture), linux(source), stage];
  const p = await exec('wsl.exe', command, { cwd: temp, windowsHide: true, timeout: 65_000, maxBuffer: 96 * 1024 });
  return JSON.parse(p.stdout);
}

