import assert from 'node:assert/strict';
import { spawn, spawnSync } from 'node:child_process';
import { randomBytes } from 'node:crypto';
import { createServer } from 'node:http';
import { copyFile, mkdir, mkdtemp, readFile, writeFile } from 'node:fs/promises';
import { join, resolve } from 'node:path';
import { setTimeout as sleep } from 'node:timers/promises';
import { fileURLToPath } from 'node:url';
import { digest, evaluate, files, fingerprint, linux, materialize } from './fixture.mjs';

const here = fileURLToPath(new URL('.', import.meta.url));
const [archiveArg, expectedSha, rep = '1', capArg = '180000', preflightArg] = process.argv.slice(2);
const preflight = preflightArg === '--preflight';
assert.ok(archiveArg && /^[a-f0-9]{64}$/u.test(expectedSha ?? ''), 'Pass candidate archive and its exact digest');
const archive = resolve(archiveArg), capMs = Number(capArg);
assert.ok(/^\d+$/u.test(rep) && Number.isSafeInteger(capMs) && capMs >= 75_000 && capMs <= 300_000);
linux(here);
linux(archive);
assert.equal(digest(await readFile(archive)), expectedSha, 'candidate package digest');
const run = await mkdtemp(join(here, 'r-'));
console.log(run);
const home = join(run, 'h'), profile = join(home, 'profiles/qa'), temp = join(run, 'tmp');
const exe = '[local-path] NEXT/DSH NEXT.exe';
const cli = '[local-path] NEXT/resources/app.asar/lib/desktop-cli.js';
const protectedPaths = ['package.json', 'pnpm-lock.yaml', 'cordis.patch.yml'].map(name => '[local-path]' + name);
const formal = () => Promise.all(protectedPaths.map(path => readFile(path).then(digest)));
const before = await formal();
const key = process.env.DEEPSEEK_API_KEY;
assert.ok(key, 'DeepSeek official API credential not available');
const diagKey = randomBytes(32).toString('base64url');
const modeOrder = Number(rep) % 2 ? ['standard', 'building-loop'] : ['building-loop', 'standard'];
const safeNames = /^(PATH|SYSTEMROOT|WINDIR|COMSPEC|PATHEXT|PROGRAMFILES(?:\(X86\))?|PROGRAMDATA|ALLUSERSPROFILE|NUMBER_OF_PROCESSORS|PROCESSOR_ARCHITECTURE|OS|LANG|LC_ALL)$/iu;
const env = { ...Object.fromEntries(Object.entries(process.env).filter(([name]) => safeNames.test(name))),
  DSH_HOME: home, DSH_DESKTOP_NEXT_HOME: home, ELECTRON_RUN_AS_NODE: '1', DSH_TELEMETRY_DISABLED: '1',
  APPDATA: join(run, 'r'), LOCALAPPDATA: join(run, 'l'), USERPROFILE: home, TEMP: temp, TMP: temp,
  DEEPSEEK_API_KEY: key, NO_PROXY: '127.0.0.1,localhost', NPM_CONFIG_USERCONFIG: join(run, 'user.npmrc'),
  NPM_CONFIG_GLOBALCONFIG: join(run, 'global.npmrc'), GIT_CONFIG_NOSYSTEM: '1', GIT_CONFIG_GLOBAL: join(run, 'git.config'), GIT_TERMINAL_PROMPT: '0' };
const context = { cwd: run, env, windowsHide: true, encoding: 'utf8' };
const call = (...args) => spawnSync(exe, ['--expose-internals', cli, ...args], { ...context, timeout: 90_000 });
const out = (name, content) => writeFile(join(run, name), typeof content === 'string' ? content : JSON.stringify(content, null, 2) + '\n');
const redact = value => String(value ?? '').replaceAll(key, '[redacted]').replaceAll(diagKey, '[redacted]').replace(/([?&]token=)[^\s"'<>]+/giu, '$1[redacted]');
const yaml = value => JSON.stringify(String(value).replaceAll('\\','/'));
const metadata = { archiveSha256: expectedSha, fixtureSha256: digest(await readFile(join(here, 'assess.py'))),
  rep, modeOrder, capMs, preflight, startedAt: new Date().toISOString() };
let host, server, stdout = '', stderr = '';

function createDiagnostics(caseInventory) {
  const observed = new Map();
  return createServer(async (req, res) => {
    if (req.method !== 'POST' || req.url !== '/engineering-check' || req.headers.authorization !== 'Bearer ' + diagKey) {
      res.writeHead(404).end();
      return;
    }
    try {
      const chunks = [];
      let length = 0;
      for await (const chunk of req) {
        length += chunk.length;
        if (length > 2_097_152) throw Error('diagnostics payload cap');
        chunks.push(chunk);
      }
      const q = JSON.parse(Buffer.concat(chunks));
      const stage = q.checkSet === 'engineering-g1' ? 'g1' : q.checkSet === 'engineering-g2' ? 'g2' : undefined;
      const envelope = { spec: 'building-loop/diagnostics/2', requestId: q.requestId, snapshotSha256: q.snapshotSha256 };
      if (!stage || q.spec !== envelope.spec || q.operation !== 'check' || !Array.isArray(q.artifacts) ||
          JSON.stringify(q.artifacts.map(item => item.path)) !== JSON.stringify(files) || typeof q.requestId !== 'string' ||
          !/^[a-f0-9]{64}$/u.test(q.snapshotSha256)) throw Error('unexpected diagnostics contract');
      for (const ids of [q.protectedCases, q.requiredCases]) {
        if (!Array.isArray(ids) || ids.some(id => !caseInventory[stage].includes(id))) throw Error('unregistered case');
      }
      const source = Object.fromEntries(q.artifacts.filter(item => item.sha256 !== null).map(item => {
        const bytes = Buffer.from(item.contentBase64, 'base64');
        if (digest(bytes) !== item.sha256) throw Error('diagnostics artifact integrity');
        return [item.path, bytes];
      }));
      const hash = fingerprint(source);
      const slot = stage + '-' + hash;
      if (!observed.has(slot)) {
        const location = join(run, 'diag', slot);
        materialize(location, source);
        observed.set(slot, evaluate({ fixture: join(here, 'assess.py'), temp, source: location, stage })
          .catch(() => null));
      }
      const output = await observed.get(slot);
      if (!output) { observed.delete(slot); res.end(JSON.stringify({ ...envelope, status: 'unavailable' })); return; }
      const cases = new Map(output.cases.map(item => [item.id, item]));
      const describe = item => ({ caseId: item.id, message: String(item.failure ?? 'failed').replace(/[\x00-\x08\x0b-\x1f\x7f]/gu, '').slice(0, 1100) });
      const first = q.protectedCases.map(id => cases.get(id)).find(item => item.status !== 'passed');
      const old = first ? { status: 'failed', firstError: describe(first) } : { status: 'passed' };
      const required = q.requiredCases.map(id => {
        const item = cases.get(id);
        return item.status === 'passed' ? { caseId: id, status: 'passed' } : { caseId: id, status: 'failed', error: describe(item) };
      });
      const status = old.status === 'passed' && required.every(item => item.status === 'passed') ? 'passed' : 'failed';
      res.writeHead(200, { 'Content-Type': 'application/json' }).end(JSON.stringify({ ...envelope, status, old, required }));
    } catch { res.writeHead(400).end(); }
  });
}

try {
  await Promise.all([home, env.APPDATA, env.LOCALAPPDATA, temp].map(path => mkdir(path, { recursive: true })));
  await Promise.all([env.NPM_CONFIG_USERCONFIG, env.NPM_CONFIG_GLOBALCONFIG, env.GIT_CONFIG_GLOBAL].map(path => writeFile(path, '')));
  const wsl = spawnSync('wsl.exe', ['-d', 'Ubuntu', '--exec', '/usr/bin/env', 'TMPDIR=' + linux(temp), 'PYTHONDONTWRITEBYTECODE=1',
    '/usr/bin/python3', linux(join(here, 'assess.py')), '--cases'], { ...context, timeout: 30_000 });
  assert.equal(wsl.status, 0, redact(wsl.stderr));
  const inventory = JSON.parse(wsl.stdout);
  server = createDiagnostics(inventory);
  await new Promise((accept, reject) => server.once('error', reject).listen(0, '127.0.0.1', accept));
  env.DSH_BUILDING_LOOP_DIAGNOSTICS_URL = 'http://127.0.0.1:' + server.address().port + '/engineering-check';
  env.DSH_BUILDING_LOOP_DIAGNOSTICS_TOKEN = diagKey;
  env.DSH_BUILDING_LOOP_DIAGNOSTICS_TIMEOUT_MS = '26000';
  let init = call('--profile', 'qa', '--from-default-profile', 'web', '--help');
  for (let n = 0; n < 2 && init.status !== 0 && /EPERM.*rename/u.test(init.stderr ?? ''); n++) {
    await sleep(500 * (n + 1));
    init = call('--profile', 'qa', '--from-default-profile', 'web', '--help');
  }
  assert.equal(init.status, 0, redact(init.error?.message ?? init.stderr));
  const installed = call('plugin', '--profile', 'qa', 'add', archive, '--offline', '--store-dir', join(run, 'pnpm-store'));
  await out('install.log', redact((installed.stdout ?? '') + '\n' + (installed.stderr ?? '')));
  assert.equal(installed.status, 0, redact(installed.error?.message ?? installed.stderr));
  metadata.version = JSON.parse(await readFile(join(profile, 'node_modules/dsh-building-loop/package.json'), 'utf8')).version;
  await Promise.all(['witness.mjs','fixture.mjs'].map(name => copyFile(join(here, name), join(profile, name))));
  await writeFile(join(profile, 'cordis.patch.yml'), `- id: session-telemetry-otel
  disabled: true
- id: product-analytics
  disabled: true
- id: session-title-llm
  disabled: true
- id: llm-deepseek-account
  disabled: true
- id: llm-deepseek
  config:
    thinking: disabled
    maxTokens: 12288
- insert:
    - id: building-loop-engineering-comparison-witness
      name: ./witness.mjs
      config:
        run: ${yaml(run)}
        home: ${yaml(home)}
        fixtures: ${yaml(here)}
        capMs: ${capMs}
        preflight: ${preflight}
        modes: ${JSON.stringify(modeOrder)}
        caseInventory: ${JSON.stringify(inventory)}
`);
  await out('metadata.json', metadata);
  host = spawn(exe, ['--expose-internals', cli, '--profile', 'qa', '--no-open', '--host', '127.0.0.1', '--port', '0'],
    { ...context, stdio: ['ignore', 'pipe', 'pipe'] });
  host.stdout.on('data', data => { stdout += data; });
  host.stderr.on('data', data => { stderr += data; });
  host.on('error', error => { stderr += error.message; });
  const deadline = Date.now() + capMs * 2 + 115_000;
  while (Date.now() < deadline && host.exitCode === null) {
    let result;
    try { result = JSON.parse(await readFile(join(run, 'result.json'), 'utf8')); } catch {}
    if (result) {
      metadata.status = result.error || result.lanes?.some(lane => lane.error) ? 'fixture-error' : 'observed';
      console.log(redact(result.error ?? JSON.stringify(result.lanes?.map(lane => lane.error ?? [lane.mode,
        lane.stages.map(stage => [stage.stage, stage.nativePhase, stage.final.cases.filter(item => item.status === 'passed').length])]))));
      break;
    }
    await sleep(450);
  }
  metadata.status ??= host.exitCode === null ? 'runner-timeout' : 'host-exited';
  if (metadata.status !== 'observed') process.exitCode = 1;
} catch (error) {
  metadata.status = 'runner-error';
  metadata.error = redact(error.stack);
  console.error(metadata.error);
  process.exitCode = 1;
} finally {
  if (host?.exitCode === null) {
    host.kill();
    await Promise.race([new Promise(accept => host.once('exit', accept)), sleep(2500)]);
  }
  server?.closeAllConnections();
  server?.close();
  metadata.finishedAt = new Date().toISOString();
  metadata.formalProfileFingerprintsUnchanged = JSON.stringify(before) === JSON.stringify(await formal());
  await Promise.all([out('metadata.json', metadata), out('host.stdout.log', redact(stdout)), out('host.stderr.log', redact(stderr))]);
}

