"""Normalize release records at the input boundary."""
from collections.abc import Mapping


class JournalError(ValueError):
    pass


def _is_int(value):
    # Integers exclude booleans: True is a subclass of int, so type() identity is required.
    return type(value) is int


def _nonempty_str(value):
    return isinstance(value, str) and bool(value)


def read_changes(changes):
    """Validate and collapse the change records.

    Replay identity: "identical" means equal id, component, units and dependency *set*.
    The dependency set is folded into a frozenset so [a, b] and [b, a] are the same
    record, and a repeated id with equal content collapses to a single record that is
    counted exactly once before graph construction and budget accounting.
    """
    if not isinstance(changes, list):
        raise JournalError("invalid-change")
    collapsed = {}
    for row in changes:
        if isinstance(row, Mapping):
            row = dict(row)
        if not isinstance(row, dict):
            raise JournalError("invalid-change")
        if not _nonempty_str(row.get("id")) or not _nonempty_str(row.get("component")):
            raise JournalError("invalid-change")
        if not _is_int(row.get("units")) or row["units"] < 1:
            raise JournalError("invalid-change")
        depends_on = row.get("depends_on")
        if depends_on is None:
            depends_on = []
        if not isinstance(depends_on, list):
            raise JournalError("invalid-change")
        deps = set()
        for dep in depends_on:
            if not _nonempty_str(dep):
                raise JournalError("invalid-change")
            deps.add(dep)
        deps = frozenset(deps)
        change_id = row["id"]
        normalized = {
            "id": change_id,
            "component": row["component"],
            "units": row["units"],
            "depends_on": deps,
        }
        previous = collapsed.get(change_id)
        if previous is None:
            collapsed[change_id] = normalized
        elif (previous["component"] != normalized["component"]
              or previous["units"] != normalized["units"]
              or previous["depends_on"] != deps):
            # Same id, different content: the journal is ambiguous, so refuse rather
            # than silently pick one of the two records.
            raise JournalError("conflicting-change")
    return list(collapsed.values())


def read_applied(applied):
    """Validate the persisted journal of already-applied change ids.

    ``applied`` is supplied by the caller and is trusted only for shape: each entry
    must be a nonempty string. Whether each id names a known change is a graph
    question and is answered by the planner.
    """
    if applied is None:
        return frozenset()
    if not isinstance(applied, list):
        raise JournalError("invalid-change")
    return frozenset(_require_id(entry) for entry in applied)


def _require_id(entry):
    if not _nonempty_str(entry):
        raise JournalError("invalid-change")
    return entry

