"""JSON transport for the release planner."""
import json
import sys

from planner import plan


def _error(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def main():
    try:
        request = json.load(sys.stdin)
    except (ValueError, TypeError):
        # One malformed request must still answer with one JSON object and exit 0.
        result = _error("invalid-json")
    else:
        try:
            result = plan(request)
        except Exception:
            # Last-resort guard: the process contract is "always one JSON object, exit 0",
            # so an unforeseen defect fails closed as invalid-request instead of a traceback.
            result = _error("invalid-request")
    print(json.dumps(result, separators=(",", ":")))


if __name__ == "__main__":
    main()

