"""Compose policy and journal data into a plan."""
import heapq

from journal import JournalError, read_applied, read_changes, read_retain
from policy import FROZEN_ERROR, PolicyError, limit_for


def failure(code):
    # Every refusal funnels through here so a failure can never carry partial actions.
    return {"status": "error", "error": code, "actions": [], "units": 0}


def topological_order(changes):
    """Return every change id in deterministic dependency order.

    Graph direction: an edge runs from a dependency to the change that declares it
    (``dep`` -> ``id``), so a change becomes eligible only after all of its
    dependencies were emitted. Ties between simultaneously eligible changes are
    broken by plain string order of the id, which makes the sequence a pure function
    of the graph and independent of the caller's array order.
    """
    units = {change["id"]: change["units"] for change in changes}
    remaining = {change["id"]: set(change["depends_on"]) for change in changes}
    dependents = {change_id: set() for change_id in units}
    for change in changes:
        for dep in change["depends_on"]:
            # Unknown targets are a graph error, not a quietly ignored edge.
            if dep not in units:
                raise JournalError("unknown-dependency")
            dependents[dep].add(change["id"])
    for change in changes:
        if change["id"] in change["depends_on"]:
            raise JournalError("dependency-cycle")

    ready = [change_id for change_id, deps in remaining.items() if not deps]
    heapq.heapify(ready)
    order = []
    while ready:
        change_id = heapq.heappop(ready)
        order.append(change_id)
        for dependent in dependents[change_id]:
            pending = remaining[dependent]
            pending.discard(change_id)
            if not pending:
                heapq.heappush(ready, dependent)
    if len(order) != len(units):
        # Anything left has an unsatisfied dependency and therefore sits on a cycle.
        raise JournalError("dependency-cycle")
    return order, units


def retained_closure(retain, applied, changes):
    """Return the applied changes that a rollback must keep, including their deps.

    ``retain`` may only name changes the journal already reports as applied; keeping a
    change that was never applied would silently drop it from the plan instead of
    refusing an inconsistent request, so that case is ``invalid-retain``.

    A retained change cannot stay consistent on its own: whatever it still depends on
    has to remain installed, otherwise the retained component would reference a
    dependency this rollback just removed. The closure therefore walks ``depends_on``
    transitively and keeps every *applied* transitive dependency. Dependencies that are
    not applied are left out because there is nothing to keep -- the caller's journal
    already treats them as absent and the rollback never emits them.
    """
    if not isinstance(retain, frozenset):
        raise JournalError("invalid-retain")
    unknown = retain - applied
    if unknown:
        raise JournalError("invalid-retain")
    depends_on = {change["id"]: change["depends_on"] for change in changes}
    kept = set(retain)
    pending = list(retain)
    while pending:
        change_id = pending.pop()
        for dep in depends_on[change_id]:
            if dep in applied and dep not in kept:
                kept.add(dep)
                pending.append(dep)
    return kept


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    # G2 is staging-only. The freeze is decided by the policy layer alone and before any
    # change or graph validation, so a frozen environment answers "production-frozen"
    # even for a malformed graph; nothing below is allowed to run for it.
    try:
        action, budget = limit_for(request)
    except PolicyError as exc:
        return failure(str(exc))
    # limit_for lets staging through even though it is the only supported environment, so
    # this guard is what actually holds the staging-only guarantee: anything that passed
    # the policy gate but is not staging fails here, still before read_changes/graph work.
    if request.get("environment") != "staging":
        return failure(FROZEN_ERROR)
    try:
        changes = read_changes(request.get("changes"))
        applied = read_applied(request.get("applied"))
        order, units = topological_order(changes)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))

    # A journal entry that names no known change is a corrupt journal, refused before
    # any ordering or budget decision can mask it.
    if applied - set(units):
        return failure("unknown-dependency")
    # Retention is checked after the graph so a retain id can be judged against both the
    # known changes and the applied journal. G2 applies it to rollback only: a plan must
    # ignore ``retain`` entirely and never be refused by it.
    try:
        retain = read_retain(request.get("retain")) if action == "rollback" else frozenset()
        if action == "rollback":
            keep = retained_closure(retain, applied, changes)
    except JournalError as exc:
        return failure(str(exc))

    if action == "rollback":
        # Rollback undoes the full deterministic order in reverse, but emits only the
        # changes the journal says are live; the budget is validated in policy and
        # deliberately does not cap a rollback.
        emitted = [change_id for change_id in reversed(order)
                   if change_id in applied and change_id not in keep]
    else:
        # Applied changes keep satisfying dependencies downstream, yet they are not
        # re-executed and their units do not count against the new budget.
        emitted = [change_id for change_id in order if change_id not in applied]
        total = sum(units[change_id] for change_id in emitted)
        # ``budget`` is already the staging effective budget (min(request, ceiling)), so
        # comparing the post-replay total against it enforces the G2 quota.
        if total > budget:
            return failure("budget-exceeded")
    total = sum(units[change_id] for change_id in emitted)
    return {"status": "ok", "actions": emitted, "units": total}

