"""Normalize release records at the input boundary."""


class JournalError(ValueError):
    pass


def _is_text(value):
    # A change ID is a nonempty string; numbers or booleans are not IDs even when
    # they could stringify to something usable, so reject them at the boundary.
    return isinstance(value, str) and value != ""


def _read_dependencies(row):
    """Return the dependency set, or raise for anything that is not a flat ID list.

    The set drops ordering and repeats, so ["a","b"] and ["b","a"] describe the
    same record. Normalizing here (not in the planner) keeps replay identity and
    graph input built from the exact same value.
    """
    depends_on = row.get("depends_on", [])
    if not isinstance(depends_on, list):
        raise JournalError("invalid-change")
    for target in depends_on:
        if not _is_text(target):
            raise JournalError("invalid-change")
    return frozenset(depends_on)


def read_changes(records):
    """Parse change records into a deduplicated list of replay-safe entries.

    Identity covers id, component, units and the dependency *set*. Identical
    records collapse to one entry before accounting and graph construction, while
    one id carrying two different identities fails as conflicting-change instead
    of guessing which record the caller meant: a wrong guess would schedule a
    release against a history that was never recorded. units uses type() because
    bool is a subclass of int and must not count as an amount.
    """
    if not isinstance(records, list):
        raise JournalError("invalid-change")
    seen = {}
    changes = []
    for row in records:
        if (not isinstance(row, dict) or not _is_text(row.get("id"))
                or not _is_text(row.get("component"))
                or type(row.get("units")) is not int or row["units"] < 1):
            raise JournalError("invalid-change")
        change = {
            "id": row["id"],
            "component": row["component"],
            "units": row["units"],
            "depends_on": _read_dependencies(row),
        }
        identity = (change["id"], change["component"], change["units"], change["depends_on"])
        known = seen.get(change["id"])
        if known is None:
            seen[change["id"]] = identity
            changes.append(change)
        elif known != identity:
            raise JournalError("conflicting-change")
    return changes


def read_applied(values):
    """Return the persisted release journal as a de-duplicated list of IDs.

    This list is caller-supplied history, not new work: a repeated ID means
    "already released once", so duplicates are folded rather than rejected.
    Membership — not order — is what the planner consults, because rollback order
    must come from the deterministic topological order, not from history order.
    """
    if not isinstance(values, list):
        raise JournalError("invalid-change")
    applied = []
    for value in values:
        if not _is_text(value):
            raise JournalError("invalid-change")
        if value not in applied:
            applied.append(value)
    return applied

