"""Compose policy and journal data into a plan."""
from journal import JournalError, read_applied, read_changes
from policy import PolicyError, limit_for


def failure(code):
    """Build the only legal failure shape; it never carries partial actions."""
    return {"status": "error", "error": code, "actions": [], "units": 0}


def load(request):
    """Validate policy and journal input, returning (budget, action, applied, changes).

    Policy is checked first so an unauthorized environment/action is reported even
    if the change records are also malformed. Changes arrive already replayed and
    deduplicated; nothing downstream re-counts the caller's raw list.
    """
    budget = limit_for(request)
    changes = read_changes(request.get("changes"))
    applied = read_applied(request.get("applied", []))
    return budget, request["action"], applied, changes


def order_changes(changes, applied):
    """Return the full deterministic topological order as a list of change IDs.

    Graph direction: an edge points from a dependency to the change that needs it,
    so a change becomes eligible only once every prerequisite has been emitted.
    Among eligible changes the lexicographically smallest ID wins, which makes the
    order independent of input order. Remaining nodes after draining mean a cycle
    (self-dependency included), reported as one failure rather than a partial plan.
    """
    by_id = {change["id"]: change for change in changes}
    for change in changes:
        for target in change["depends_on"]:
            if target not in by_id:
                raise JournalError("unknown-dependency")
    for entry in applied:
        if entry not in by_id:
            raise JournalError("unknown-dependency")

    # The full order is built over every change, including already applied ones:
    # rollback inverts this complete order, and pruning applied nodes first would
    # drop the very entries rollback has to emit and could hide their cycles.
    satisfied = set()
    remaining = [by_id[k] for k in sorted(by_id)]
    order = []
    while remaining:
        for index, change in enumerate(remaining):
            if change["depends_on"] <= satisfied:
                break
        else:
            # Nothing is eligible but work remains: the leftover subgraph is cyclic.
            raise JournalError("dependency-cycle")
        order.append(change["id"])
        satisfied.add(change["id"])
        del remaining[index]
    return order


def select(action, order, applied):
    """Pick the actions to emit.

    plan follows the topological order forward and skips already released IDs;
    their dependencies are already satisfied because the full order is built.
    rollback walks the *full* order in reverse and keeps only applied IDs: reversing
    a subset would put dependents back in front of their dependencies, so the whole
    order must be inverted even though unapplied entries are dropped afterwards.
    """
    done = set(applied)
    if action == "plan":
        return [change_id for change_id in order if change_id not in done]
    return [change_id for change_id in reversed(order) if change_id in done]


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        budget, action, applied, changes = load(request)
        order = order_changes(changes, applied)
        actions = select(action, order, applied)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))
    emitted = set(actions)
    units = sum(change["units"] for change in changes if change["id"] in emitted)
    # Budget is a rollout cap measured on emitted units only, so it is applied after
    # replay/deduplication and after already applied work is filtered out. Rollback
    # still validates the budget but must never be truncated by it.
    if action == "plan" and units > budget:
        return failure("budget-exceeded")
    return {"status": "ok", "actions": actions, "units": units}

