"""Compose policy and journal data into a plan.

Pipeline order is deliberate and fail-closed: structure, then frozen policy,
then journal validation/deduplication, then the graph, then replay/budget.
Each disallowed operation returns ``failure(code)`` with no partial actions.
"""
import heapq

from journal import JournalError, read_applied, read_changes, read_retain
from policy import PolicyError, limit_for


def failure(code):
    # The single failure shape: every rejection path keeps actions empty and
    # units zero, so callers never see a partially applied plan.
    return {"status": "error", "error": code, "actions": [], "units": 0}


def _order(changes):
    """Return the deterministic topological order of all changes.

    Edges point dep -> change ("depends_on" means "must run before me"). Repeated
    deps collapse to one edge so they do not inflate indegree, and any change
    depending on a missing ID fails before ordering.
    """
    by_id = {change["id"]: change for change in changes}
    dependents = {change_id: [] for change_id in by_id}
    indegree = {change_id: 0 for change_id in by_id}
    for change in changes:
        for dep in set(change["depends_on"]):
            if dep not in by_id:
                raise JournalError("unknown-dependency")
            dependents[dep].append(change["id"])
            indegree[change["id"]] += 1
    # Lexicographic tie-breaking: among all currently eligible (indegree 0)
    # changes pick the smallest ID. The min-heap makes that choice stable, so
    # plan order and rollback order both derive from one canonical sequence.
    eligible = [change_id for change_id, count in indegree.items() if count == 0]
    heapq.heapify(eligible)
    order = []
    while eligible:
        current = heapq.heappop(eligible)
        order.append(current)
        for nxt in dependents[current]:
            indegree[nxt] -= 1
            if indegree[nxt] == 0:
                heapq.heappush(eligible, nxt)
    # A self-loop or any cycle leaves nodes permanently blocked; report that as
    # a cycle rather than returning a silently truncated order.
    if len(order) != len(changes):
        raise JournalError("dependency-cycle")
    return order


def _retained(changes, applied, order, retain):
    """Return the rollback-safe closure of ``retain`` over applied changes.

    Undoing a change while a still-retained change depends on it would leave the
    retained change without its prerequisite, so retention propagates along
    ``depends_on`` (from a retained ID to everything it needs). Only applied
    entries are held: an unapplied dependency is not part of this rollback and
    must not shift the emitted sequence. Progress is bounded by ``order`` so a
    dependency outside the graph cannot loop forever.
    """
    remaining = {change["id"]: {dep for dep in change["depends_on"] if dep in applied}
                 for change in changes}
    held = set(retain)
    pending = [change_id for change_id in order if change_id in held]
    while pending:
        for dep in remaining.get(pending.pop(), ()):
            if dep not in held:
                held.add(dep)
                pending.append(dep)
    return held


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        # limit_for runs before read_changes on purpose: G2 freezes production
        # ahead of graph and change validation, so a malformed production
        # request still reports production-frozen and never reaches the graph.
        action, limit, caps = limit_for(request)
        changes = read_changes(request.get("changes"))
        applied = read_applied(request.get("applied", []), changes)
        # retain is rollback-only; validating it here too would break plan
        # requests that merely carry a stale field (G1 compatibility).
        retain = read_retain(request.get("retain"), applied) if action == "rollback" else frozenset()
        order = _order(changes)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))
    units_by_id = {change["id"]: change["units"] for change in changes}
    if action == "rollback":
        # Reuse the same canonical order as plan and walk it backwards, so a
        # dependent is always undone before the change it depends on. Emit only
        # applied changes outside the retained closure; the budget was validated
        # but must not gate an undo.
        held = _retained(changes, applied, order, retain)
        emitted = [change_id for change_id in reversed(order)
                   if change_id in applied and change_id not in held]
    else:
        # Replay first: already-applied changes stay in the order (they satisfy
        # dependencies for their dependents) but are not re-emitted and their
        # units never count against the budget.
        emitted = [change_id for change_id in order if change_id not in applied]
    units = sum(units_by_id[change_id] for change_id in emitted)
    # Budget is checked against the sum of emitted units, never the raw input
    # total, and only where policy says it caps; ``limit`` already folds in the
    # staging quota, so a generous request budget cannot raise the real ceiling.
    if caps and units > limit:
        return failure("budget-exceeded")
    return {"status": "ok", "actions": emitted, "units": units}

