"""Compose policy and journal data into a plan."""
# Import direction: planner may import policy and journal; neither may import
# planner back. This keeps transport (release.py) unaware of domain rules.
import heapq

from journal import (JournalError, expand_retain, read_applied, read_retain,
                     replay)
from policy import PolicyError, limit_for


def failure(code):
    # Every failure is the same closed shape: no partial actions, zero units.
    return {"status": "error", "error": code, "actions": [], "units": 0}


def _build_edges(changes):
    """Map each change id to its dependency ids, or fail on an unknown target.

    Edges point dependency -> dependent in spirit, but are stored as
    "id wants these prerequisites". An unknown target means the graph is
    incomplete, so admitting it would risk emitting a change before something
    it requires: fail closed with unknown-dependency.
    """
    known = {change["id"] for change in changes}
    edges = {}
    for change in changes:
        for name in change["depends_on"]:
            if name not in known:
                raise JournalError("unknown-dependency")
        edges[change["id"]] = list(change["depends_on"])
    return edges


def _topological_order(changes):
    """Full deterministic topological order of all changes, or dependency-cycle.

    Determinism comes from a min-heap of eligible ids, so ties break by
    lexicographic id rather than input order: the same request always yields
    the same rollout, and rollback can mirror it exactly. The order covers
    applied and unapplied changes alike; callers filter afterwards.
    """
    edges = _build_edges(changes)
    remaining = {cid: len(deps) for cid, deps in edges.items()}
    dependents = {cid: [] for cid in edges}
    for cid, deps in edges.items():
        for name in deps:
            dependents[name].append(cid)
    ready = [cid for cid, count in remaining.items() if count == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        current = heapq.heappop(ready)
        order.append(current)
        for child in dependents[current]:
            remaining[child] -= 1
            if remaining[child] == 0:
                heapq.heappush(ready, child)
    if len(order) != len(edges):
        # Leftover nodes are exactly those on or behind a cycle.
        raise JournalError("dependency-cycle")
    return order


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        # Policy is checked first so environment/action/budget errors win over
        # record errors, matching the documented transport code precedence.
        # G2 relies on this order: limit_for() refuses production before
        # replay() ever touches `changes`, so a frozen request returns
        # production-frozen even when the graph is malformed.
        budget = limit_for(request)
        # replay() collapses identical duplicates before any accounting: a
        # retried journal append must not double-charge budget or add edges.
        changes = replay(request.get("changes"))
        applied = read_applied(request.get("applied"), {c["id"] for c in changes})
        order = _topological_order(changes)
        kept = set()
        if request.get("action") == "rollback":
            # G2 retention is rollback-only: a `retain` on plan is inert. It is
            # resolved after the graph exists because the transitive closure
            # follows dependency edges in the same "id wants prerequisites"
            # direction as the order. An acyclic order is already proven here,
            # which is the precondition expand_retain() documents.
            deps_by_id = {change["id"]: change["depends_on"] for change in changes}
            retain = read_retain(request.get("retain"),
                                 {c["id"] for c in changes}, applied)
            kept = expand_retain(retain, applied, deps_by_id)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))
    units_by_id = {change["id"]: change["units"] for change in changes}
    if request.get("action") == "rollback":
        # Build the reverse from the *full* order, then keep applied entries:
        # a local re-sort of the applied subset could tear down a prerequisite
        # before its dependent. Budget is validated but deliberately not
        # enforced, so a safety rollback is never blocked by quota.
        # `kept` filters after that ordering, never re-sorts it, so retained
        # ids (and their applied prerequisites) drop out while the rest keep
        # their original relative order.
        actions = [cid for cid in reversed(order)
                   if cid in applied and cid not in kept]
        return {"status": "ok", "actions": actions,
                "units": sum(units_by_id[cid] for cid in actions)}
    # Forward plan: already applied ids are skipped and do not consume budget,
    # but they still satisfy dependencies through the full order above.
    actions = [cid for cid in order if cid not in applied]
    units = sum(units_by_id[cid] for cid in actions)
    if units > budget:
        return failure("budget-exceeded")
    return {"status": "ok", "actions": actions, "units": units}
